#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> K(n);
    vector<vector<pair<int,int>>> orig(n);

    for(int i=0;i<n;i++){
        cin >> K[i];
        orig[i].resize(K[i]);
        for(int j=0;j<K[i];j++){
            cin >> orig[i][j].first >> orig[i][j].second;
        }
    }

    // Transform: first flip (if f=1, negate x), then rotate r times CCW 90°
    // CCW 90°: (x,y) -> (-y, x)
    auto transform = [&](const vector<pair<int,int>>& cells, int f, int r) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x,y] : cells){
            int nx = x, ny = y;
            if(f) nx = -nx;
            for(int q=0; q<r; q++){
                int tmp = nx;
                nx = -ny;
                ny = tmp;
            }
            res.push_back({nx, ny});
        }
        // Normalize to non-negative
        int minx = INT_MAX, miny = INT_MAX;
        for(auto [x,y] : res){ minx=min(minx,x); miny=min(miny,y); }
        for(auto& [x,y] : res){ x-=minx; y-=miny; }
        return res;
    };

    // Simple greedy: place pieces in a strip, sorted by size descending
    // Use a wide strip and heightmap-based BL placement

    int totalCells = 0;
    for(int i=0;i<n;i++) totalCells += K[i];

    long long bestArea = LLONG_MAX;
    int bestW=0, bestH=0;
    struct PR { int x,y,r,f; };
    vector<PR> bestPl(n);

    vector<int> order(n);
    iota(order.begin(),order.end(),0);
    sort(order.begin(),order.end(),[&](int a,int b){ return K[a]>K[b]; });

    double sq = sqrt((double)totalCells);

    for(double mult=0.6; mult<=2.5; mult+=0.1){
        int W = max(10, (int)(sq*mult));
        int maxH = totalCells/W + 200;
        maxH = min(maxH, totalCells+100);
        if((long long)W*maxH > 10000000LL) maxH = 10000000/W;

        vector<int> hmap(W, 0);
        vector<PR> placements(n);
        int curMaxY=0;
        bool failed=false;

        for(int idx=0; idx<n && !failed; idx++){
            int pi = order[idx];
            int bs=INT_MAX, bx=-1, by=-1, bf=0, br=0;

            for(int f=0;f<2;f++) for(int r=0;r<4;r++){
                auto cells = transform(orig[pi], f, r);
                int w=0, h=0;
                for(auto [cx,cy]:cells){ w=max(w,cx+1); h=max(h,cy+1); }
                if(w>W) continue;

                for(int x=0;x<=W-w;x++){
                    int minY=0;
                    for(auto [cx,cy]:cells) minY=max(minY, hmap[x+cx]-cy);
                    int topY=0;
                    for(auto [cx,cy]:cells) topY=max(topY, minY+cy+1);
                    if(topY<=maxH && topY<bs){
                        bs=topY; bx=x; by=minY; bf=f; br=r;
                    }
                }
            }
            if(bx<0){failed=true;break;}
            auto cells = transform(orig[pi], bf, br);
            for(auto [cx,cy]:cells){
                hmap[bx+cx]=max(hmap[bx+cx], by+cy+1);
                curMaxY=max(curMaxY, by+cy+1);
            }
            placements[pi]={bx, by, br, bf};
        }
        if(failed) continue;
        long long area=(long long)W*curMaxY;
        if(area<bestArea){ bestArea=area; bestW=W; bestH=curMaxY; bestPl=placements; }
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++)
        cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
